mapper.select:
select
    notice.*,
    company.company_name as company_name,
    seeker.username as job_seeker_name,
    creator.username as creator_name
from t_interview_notice notice
    LEFT JOIN t_company company on notice.company_id = company.company_id
    LEFT JOIN t_user seeker on notice.job_seeker_id = seeker.user_id
    LEFT JOIN t_user creator on notice.creator_id = creator.user_id
where notice.is_deleted = 0

    and notice.company_id = #{dto.companyId}


    and notice.job_seeker_id = #{dto.jobSeekerId}


    and notice.status = #{dto.status}


    and notice.interview_type = #{dto.interviewType}


    and notice.interview_start_time >= #{dto.startTime}


    and notice.interview_end_time <= #{dto.endTime}

order by notice.interview_start_time desc

select count(1)
from t_interview_notice notice
    left join t_interview_notice_participant participant
        on notice.id = participant.interview_notice_id and participant.is_deleted = 0
where notice.is_deleted = 0
  and notice.status in (0, 1)
  and notice.interview_start_time < #{endTime}
  and notice.interview_end_time > #{startTime}
  and notice.id <> ifnull(#{excludeId}, -1)
  and (
    notice.job_seeker_id = #{userId}
    or participant.user_id = #{userId}
  )
